import json
from pathlib import Path
import subprocess
import sys
import unittest


class ReportTests(unittest.TestCase):
    def run_cli(self, *args):
        return subprocess.check_output([sys.executable, str(Path(__file__).resolve().parents[1] / "report.py"), *args], text=True)

    def test_text(self):
        self.assertEqual(self.run_cli("2", "3"), "5\n")

    def test_json(self):
        self.assertEqual(json.loads(self.run_cli("--json", "2", "3")), {"count": 2, "total": 5})

